metrics.final_dsl:
workspace "Bookshop" "A simple online bookshop" {

    model {
        customer = person "Customer" "A customer who browses the catalogue and buys books online."
        bookshop = softwareSystem "Bookshop" "An online bookshop where customers browse the catalogue, place orders and pay for books." {
            webStore = container "Web Store" "The web application customers use to browse the catalogue and place orders." "Java / Spring Boot"
            orderProcessor = container "Order Processor" "Processes orders, takes payment and dispatches books." "Java / Spring Batch"

            customer -> webStore "Browses the catalogue and places orders" "HTTPS"
            webStore -> orderProcessor "Submits new orders to" "REST/JSON"
        }
    }

    views {
        systemContext bookshop "systemContext" "Shows the Customer and the Bookshop system." {
            include *
            autoLayout
        }
        container bookshop "containers" "Shows the containers inside the Bookshop system." {
            include *
            autoLayout
        }
    }

    configuration {
        scope SoftwareSystem
    }
}

